// Package container embeds the files needed to build Pact's agent image.
package container

import (
	"embed"
	"io/fs"
)

// contextFiles contains the entire Docker build context, including the Linux
// Git helpers generated by p-git-client before the launcher is built.
//
//go:embed context
var contextFiles embed.FS

// BuildContext is the Dockerfile and its COPY inputs, without the directory prefix.
var BuildContext, _ = fs.Sub(contextFiles, "context")
